// План: specs/notifications.md, блок 2. Кейсы: .qa/tests/notifications/NTF-001, .qa/tests/deals/DEAL-001.
// Тикеты #ccd9d865bc2f2ee955f517d1 (клик по уведомлению сделки) и #1846ecd8bbe90de4c58d0f23 («מוצגת לשני הצדדים»).
// Несколько ролей: клиент (0500000004, «יונתן לוי») создаёт сделку, נותן שירות (0500000005, «שירה כהן») получает уведомление.
// Создаёт сделку QA-AUTO-התראה … ₪5 без депозита → @data; id — в qa-auto-created.jsonl (чистка в БД).
import { test, expect } from '../../fixtures';
import { PROVIDER_ID, recordCreated, stamp, waitWithReload } from '../disputes/helpers';

test.describe.configure({ mode: 'serial', retries: 0 });

// Признак «прочитано» — только фон карточки (aria-признака нет; проверено 08.10).
const UNREAD_BG = 'rgb(232, 245, 254)';
const READ_BG = 'rgb(255, 255, 255)';
const NEW_DEAL_TEXT = 'הצד השני פתח עסקה חדשה. יש לעבור על תנאי העסקה ולאשר אותם.';

let dealId = '';
let dealTitle = '';

function ddmmyyyy(daysFromNow: number): string {
  const d = new Date(Date.now() + daysFromNow * 86_400_000);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${p(d.getDate())}${p(d.getMonth() + 1)}${d.getFullYear()}`;
}

test.describe('התראות — התראת עסקה חדשה אצל נותן השירות', () => {
  test('נותן שירות: "בקשת עסקה חדשה" — לחיצה פותחת את העסקה ומסמנת כנקראה, גם אחרי רענון @android @data (#ccd9d865)', async ({ asUser }) => {
    const client = await asUser('client');
    const provider = await asUser('provider');
    dealTitle = `QA-AUTO-התראה ${stamp()}`;

    // 1. Клиент создаёт сделку с «שירה כהן» (без депозита).
    await client.goto(`/deals/new?providerId=${PROVIDER_ID}`);
    const tb = client.getByRole('textbox', { name: 'הקלד/י' });
    await tb.nth(0).fill(dealTitle);
    await client.getByRole('button', { name: /סוג העסקה/ }).click();
    await client.getByText('שיפוץ ובנייה', { exact: true }).last().click();
    await tb.nth(1).fill('QA-AUTO — עסקת בדיקה אוטומטית, לא אמיתית.');
    await tb.nth(2).fill('5');
    const dates = client.getByRole('textbox', { name: '00/00/0000' });
    await dates.nth(0).click();
    await dates.nth(0).pressSequentially(ddmmyyyy(2), { delay: 40 });
    await dates.nth(1).click();
    await dates.nth(1).pressSequentially(ddmmyyyy(9), { delay: 40 });
    await client.getByRole('button', { name: 'פתיחת עסקה בטוחה' }).last().click();
    await client.waitForURL(/\/deals\/[0-9a-f-]{36}$/, { timeout: 20_000 });
    dealId = new URL(client.url()).pathname.split('/deals/')[1];
    recordCreated({ dealId, title: dealTitle, note: '#ccd9d865 уведомление о новой сделке' });

    // 2. Поставщик: «התראות» — ждём карточку этой сделки (с обновлением, без фиксированных пауз).
    await provider.goto('/notifications');
    const card = provider.locator('[data-testid^="notification-"]').filter({ hasText: dealTitle });
    await waitWithReload(provider, card);

    // Категория «ממתין לפעולה» (F-17 AC2), поля карточки (F-17 AC5), непрочитанная.
    await provider.getByTestId('chip-action_required').click();
    await expect(card).toBeVisible();
    await expect(card).toContainText('בקשת עסקה חדשה');
    await expect(card).toContainText('₪5');
    await expect(card).toContainText(NEW_DEAL_TEXT);
    await expect(card).toHaveCSS('background-color', UNREAD_BG);
    const cardTestId = await card.getAttribute('data-testid');
    expect(cardTestId).toBeTruthy();

    // 3. Клик открывает именно эту сделку (тикет «מה רצוי»: «פותחת את מסך העסקה הרלוונטי»).
    await card.click();
    await provider.waitForURL(new RegExp(`/deals/${dealId}$`), { timeout: 20_000 });
    await expect(provider.getByText(dealTitle).first()).toBeVisible();

    // 4. «חזרה» → «התראות», карточка прочитана — и после обновления («מסמנת אותה כנקראה»).
    await provider.getByTestId('back-button').click();
    await provider.waitForURL(/\/notifications$/);
    const sameCard = provider.getByTestId(cardTestId!);
    await expect(sameCard).toHaveCSS('background-color', READ_BG);
    await provider.reload();
    await expect(sameCard).toBeVisible();
    await expect(sameCard).toHaveCSS('background-color', READ_BG);
  });

  test('נותן שירות רואה את העסקה החדשה ב"עסקאות" (העסקה מוצגת לשני הצדדים) @android @data (#1846ecd8)', async ({ asUser }) => {
    test.skip(!dealId, 'Сделка не создана в предыдущем тесте');
    const provider = await asUser('provider');
    await provider.goto('/deals');
    await expect(provider.getByTestId('deals-title')).toBeVisible();
    // FL-04 шаг 4: «העסקה נפתחת במצב "ממתין לאישור" ומוצגת לשני הצדדים».
    await expect(provider.getByText(dealTitle).first()).toBeVisible({ timeout: 20_000 });
  });
});
